export function batchGenerators<T extends readonly APIRequestGenerator[]>(
    api: API<any>,
    ...requestGenerators: T
): ExecutedGeneratorsResults<T> {
    const results: any[] = [];
    const requestObjects: (APIRequest | undefined)[] = [];
    const completedIndices = new Set<number>();
