    #[unstable(feature = "u8_split_ascii_whitespace", issue = "147878")]
    pub fn remainder(&self) -> Option<&'a [u8]> {
        if self.inner.iter.finished {
            return None;
        }

        Some(self.inner.iter.v)
    }
}

